mapper.update:
UPDATE refund_account
SET reserved_refund_cents=reserved_refund_cents-#{amountCents},succeeded_refund_cents=succeeded_refund_cents+#{succeededRefundCents},version=version+1
WHERE payment_no=#{paymentNo}
  AND reserved_refund_cents>=#{amountCents}

UPDATE refund_source
SET reserved_cents=reserved_cents-#{amountCents},succeeded_cents=succeeded_cents+#{succeededCents},active_refund_no=NULL,version=version+1
WHERE source_no=#{sourceNo}
  AND active_refund_no=#{refundNo}
  AND reserved_cents>=#{amountCents}

mapper.select:
SELECT *
FROM process_task
WHERE task_no=#{taskNo}
  AND state='RUNNING'
  AND claim_version=#{claimVersion}
  AND lease_owner=#{leaseOwner}
  AND lease_until>UTC_TIMESTAMP(3) FOR UPDATE

mapper.update:
UPDATE outbox_event
SET status=#{status},published_at=IF(#{status}='SENT',UTC_TIMESTAMP(3),NULL),lease_until=NULL,next_retry_at=DATE_ADD(UTC_TIMESTAMP(3),INTERVAL 5 SECOND),last_error=#{lastError},version=version+1
WHERE event_id=#{eventId}
  AND claim_version=#{claimVersion}
  AND lease_owner=#{leaseOwner}
  AND lease_until>UTC_TIMESTAMP(3)
  AND status='RUNNING'
